"""Uniform, evidence-bound interpretation of model-introduced Python syntax failures.

Preserves the frozen research source and every raw result. A positive baseline
and a fresh same-image compile probe must establish the failure before a
zero-test result can be accepted as a coding failure. Original Harbor remains
the final scorer. Other unexplained invalid grades still stop the study.
"""
from pathlib import Path,PurePosixPath
import json,hashlib,re,subprocess
from osa_eval.contracts import digest
from osa_eval.swebench_pro import compiler_crashes

def adjudicate(task_id,run_dir,output,cpu,docker_prefix):
 run_dir=Path(run_dir);output=Path(output);output.mkdir(exist_ok=False);result=json.loads((run_dir/'result.json').read_text());row=next(x for x in result['rows']if x['task_id']==task_id);grade=row['grade'];assert row['valid']is False;identity=json.loads((run_dir/'identity.json').read_text());reference=identity['evaluator_gates'][task_id]['reference'];assert reference['valid']is True and reference['success']is True;assert reference['task_files']==grade['task_files'];image=grade['workspace']['image_id'];assert reference['workspace']['image_id']==image
 folder=run_dir/digest(task_id)[:20]/'pristine-grade';raw=json.loads((folder/'output.json').read_text());assert raw.get('tests')==[] and(folder/'reward.txt').read_text().strip()=='0';assert grade['apply']['returncode']==0;logs='\n'.join((folder/n).read_text(errors='replace')for n in ['run-script-stdout.txt','run-script-stderr.txt']if(folder/n).exists());assert not compiler_crashes(logs),'Compiler crash requires separate infrastructure diagnosis';assert re.search(r'\b(?:SyntaxError|IndentationError|TabError):',logs),'No unambiguous Python syntax diagnostic; preserve invalid grade'
 patch=run_dir/digest(task_id)[:20]/'model.patch';assert hashlib.sha256(patch.read_bytes()).hexdigest()==grade['patch_sha256'];changed=set()
 for line in patch.read_text().splitlines():
  if line.startswith('+++ b/'):changed.add(line[6:])
 cwd=PurePosixPath(grade['workspace']['cwd']);candidates=[]
 for path,line in re.findall(r'File "([^"\n]+\.py)", line (\d+)',logs):
  p=PurePosixPath(path)
  if p.is_relative_to(cwd)and p.relative_to(cwd).as_posix()in changed and'..'not in p.parts:candidates.append((str(p),int(line)))
 assert candidates,'Syntax diagnostic does not identify a model-modified Python file';path,line=candidates[-1];code="from pathlib import Path\nimport sys,json,hashlib,os,subprocess,tempfile\ndata=json.loads(sys.stdin.buffer.read().decode('utf-8'));name=data['path'];cwd=data['cwd'];p=Path('/sys/fs/cgroup');baseline=Path(name).read_bytes();compile(baseline,name,'exec');record={'baseline_compiles':True,'cpu.max':(p/'cpu.max').read_text().strip(),'memory.max':(p/'memory.max').read_text().strip(),'affinity':sorted(os.sched_getaffinity(0))}\nwith tempfile.TemporaryDirectory(prefix='osa-syntax-proof-')as tmp:\n patch=Path(tmp)/'model.patch';patch.write_bytes(data['patch'].encode('utf-8'));commands=[['git','apply','--verbose',str(patch)],['git','apply','--3way',str(patch)],['patch','--fuzz=3','-p1','-i',str(patch)]]\n for command in commands:\n  result=subprocess.run(command,cwd=cwd,capture_output=True,timeout=30)\n  if result.returncode==0:break\n assert result.returncode==0,result.stderr.decode(errors='replace')[-1600:]\n model=Path(name).read_bytes();record['patched_source_sha256']=hashlib.sha256(model).hexdigest();record['apply_exit']=result.returncode\n try:\n  compile(model,name,'exec');record['patched_compiles']=True\n except (SyntaxError,IndentationError,TabError)as e:\n  record.update(patched_compiles=False,error_type=type(e).__name__,line=e.lineno,offset=e.offset,message=e.msg)\nprint(json.dumps(record))"
 command=[*docker_prefix,'run','--rm','-i','--network','none','--cpus','1','--memory','4294967296','--cpuset-cpus',str(cpu),'--cap-drop','ALL','--security-opt','no-new-privileges','--entrypoint','python3',image,'-c',code];body=json.dumps({'path':path,'cwd':str(cwd),'patch':patch.read_text()}).encode('utf-8');p=subprocess.run(command,input=body,capture_output=True,timeout=120);(output/'compile-probe.stdout').write_bytes(p.stdout);(output/'compile-probe.stderr').write_bytes(p.stderr);assert p.returncode==0,p.stderr.decode(errors='replace');probe=json.loads(p.stdout);assert probe['baseline_compiles']is True and probe['patched_compiles']is False and probe['line']==line;assert probe['cpu.max']=='100000 100000'and probe['memory.max']=='4294967296'and probe['affinity']==[cpu]
 annotation={'schema_version':1,'raw_result_modified':False,'result_sha256':hashlib.sha256((run_dir/'result.json').read_bytes()).hexdigest(),'task_id':task_id,'seed':row['seed'],'architecture':row['architecture'],'original_valid':False,'original_success':row['success'],'interpreted_valid':True,'interpreted_success':False,'failure_category':'model_introduced_python_syntax_error','model_patch_sha256':grade['patch_sha256'],'syntax_file':path,'syntax_line':line,'syntax_file_sha256':probe['patched_source_sha256'],'source_materialization':'Apply captured hashverified patch in a fresh immutableimage; no originalcontainer required','same_image_compile_probe':probe,'image_id':image,'reference_output_sha256':reference['grade_source_sha256'],'independent_output_sha256':hashlib.sha256((folder/'output.json').read_bytes()).hexdigest(),'rule_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'rule':'Required unchanged positive baseline, matching task/image, patch-applied file named by syntax diagnostic, base source compiles and captured model source fails in same image, no compiler crash, independentreward0; final acceptance additionally requires originalHarbor noexception/reward0/equaltestoutput.'};(output/'annotation.json').write_text(json.dumps(annotation,indent=2));return annotation
